def _derive_history_cache_key(secret: str, user_id: str) -> tuple[str, str]:
    """Derive stable, domain-separated browser cache key material."""
    secret_bytes = secret.encode("utf-8")
    user_bytes = user_id.encode("utf-8")
    key_bytes = hmac.new(
        secret_bytes,
        _HISTORY_CACHE_KEY_DOMAIN + user_bytes,
        hashlib.sha256,
    ).digest()
    key_id = hmac.new(
        secret_bytes,
        _HISTORY_CACHE_KEY_ID_DOMAIN + user_bytes,
        hashlib.sha256,
    ).hexdigest()[:16]
    key = base64.urlsafe_b64encode(key_bytes).decode("ascii").rstrip("=")
    return key_id, key


@router.get(
    "/api/runtime/history-cache-key",
    response_model=HistoryCacheKeyOut,
)
def get_history_cache_key(request: Request, response: Response) -> HistoryCacheKeyOut:
    """Return one authenticated tenant's tab-cache encryption key."""
    tenant = require_tenant(request)
    key_id, key = _derive_history_cache_key(get_settings().secret_key, tenant.user_id)
    response.headers["Cache-Control"] = "no-store"
    response.headers["Pragma"] = "no-cache"
    return HistoryCacheKeyOut(
        version=1,
        user_id=tenant.user_id,
        key_id=key_id,
        key=key,
    )


def _safe_runtime_status(
    user_id: str,
    runtime: ManagedRuntimeStatus | None,
    *,
    expected_artifact_version: str,
) -> ManagedRuntimeOut:
    """Convert persisted state to fixed public response fields."""
    if runtime is None:
        return ManagedRuntimeOut(provider="fly_sprites", status="absent")
    runner = get_managed_runner_for_user(user_id)
    runner_public_key = None
    if (
        runner is not None
        and runner.get("id") == runtime.runner_id
        and runner.get("kind") == "managed"
        and runner.get("cloud_provider") == runtime.provider_name
        and runner.get("noise_key_confirmed")
    ):
        candidate = runner.get("noise_public_key")
        if isinstance(candidate, str) and candidate:
            runner_public_key = candidate
    return ManagedRuntimeOut(
        provider=runtime.provider_name,
        status=runtime.lifecycle_status,
        artifact_version=runtime.artifact_version,
        last_error=runtime.last_error,
        runner_public_key=runner_public_key,
        history_bundle_supported=(
            runtime.lifecycle_status == "ready"
            and runtime.artifact_version == expected_artifact_version
        ),
        runner_rpc_push_supported=(
            runtime.lifecycle_status == "ready"
            and runtime.artifact_version == expected_artifact_version
        ),
    )


