 81	function encodeBase64url(value: Uint8Array): string {
 82	  let binary = "";
 83	  for (let offset = 0; offset < value.length; offset += 0x8000) {
 84	    binary += String.fromCharCode(...value.subarray(offset, offset + 0x8000));
 85	  }
 86	  return btoa(binary)
 87	    .replace(/\+/gu, "-")
 88	    .replace(/\//gu, "_")
 89	    .replace(/=+$/u, "");
 90	}
