 92	function decodeCanonicalBase64url(
 93	  value: unknown,
 94	  expectedBytes?: number,
 95	): Uint8Array | null {
 96	  if (
 97	    typeof value !== "string" ||
 98	    value.length === 0 ||
 99	    !BASE64URL_PATTERN.test(value) ||
100	    value.length % 4 === 1
101	  ) {
102	    return null;
103	  }
104	  try {
105	    const padding = "=".repeat((4 - (value.length % 4)) % 4);
106	    const binary = atob(
107	      value.replace(/-/gu, "+").replace(/_/gu, "/") + padding,
108	    );
109	    const bytes = Uint8Array.from(binary, (character) =>
110	      character.charCodeAt(0),
111	    );
112	    if (expectedBytes !== undefined && bytes.byteLength !== expectedBytes)
113	      return null;
114	    return encodeBase64url(bytes) === value ? bytes : null;
115	  } catch {
116	    return null;
117	  }
118	}
