256	  private async fetchFreshKey(userId: string): Promise<CachedKey | null> {
257	    if (!this.cryptoProvider?.subtle) return null;
258	    let timeout: ReturnType<typeof setTimeout> | undefined;
259	    try {
260	      const response = await Promise.race([
261	        this.fetchKey(),
262	        new Promise<null>((resolve) => {
263	          timeout = setTimeout(() => resolve(null), this.keyFetchTimeoutMs);
264	        }),
