268	      const keyBytes = valid.keyBytes;
269	      try {
270	        const key = await this.cryptoProvider.subtle.importKey(
271	          "raw",
272	          toArrayBuffer(keyBytes),
273	          { name: "AES-GCM" },
274	          false,
275	          ["encrypt", "decrypt"],
276	        );
277	        return { keyId: valid.key_id, key, loadedAtMs: this.now() };
278	      } finally {
279	        keyBytes.fill(0);
280	      }
281	    } catch {
282	      return null;
283	    } finally {
284	      if (timeout !== undefined) clearTimeout(timeout);
