361	  async get(userId: string, sessionId: string): Promise<unknown[] | null> {
362	    if (!this.storage || !validateIdentity(userId, sessionId)) return null;
363	    let serialized: string | null;
364	    try {
365	      serialized = this.storage.getItem(cacheKey(userId, sessionId));
366	    } catch {
