 96	def _derive_history_cache_key(secret: str, user_id: str) -> tuple[str, str]:
 97	    """Derive stable, domain-separated browser cache key material."""
 98	    secret_bytes = secret.encode("utf-8")
 99	    user_bytes = user_id.encode("utf-8")
100	    key_bytes = hmac.new(
101	        secret_bytes,
102	        _HISTORY_CACHE_KEY_DOMAIN + user_bytes,
103	        hashlib.sha256,
104	    ).digest()
105	    key_id = hmac.new(
106	        secret_bytes,
107	        _HISTORY_CACHE_KEY_ID_DOMAIN + user_bytes,
108	        hashlib.sha256,
109	    ).hexdigest()[:16]
110	    key = base64.urlsafe_b64encode(key_bytes).decode("ascii").rstrip("=")
111	    return key_id, key
